import json
from typing import List, Dict, Optional, Union

def proc(invoices: List[Dict[str, Union[str, float]]], month: Optional[str] = None, apply_vat: bool = False) -> str:
    if not isinstance(invoices, list):
        raise ValueError("Invalid input: 'invoices' should be a list.")

    results = []
    total_amount = 0.0

    for invoice in invoices:
        if not isinstance(invoice, dict):
            raise ValueError("Invalid input: Each invoice should be a dictionary.")

        status = invoice.get('status', '').lower()
        amount = invoice.get('amount')

        if status == 'paid' and amount is not None:
            try:
                amt = float(amount)
            except (ValueError, TypeError):
                raise ValueError(f"Invalid amount for invoice {invoice.get('id')}: {amount}")

            if apply_vat:
                amt *= 1.2

            if month is None or invoice.get('date', '')[:7] == month:
                results.append({
                    'id': invoice['id'],
                    'client': invoice['client'].strip().title(),
                    'amt': round(amt, 2)
                })

    total_amount = sum(item['amt'] for item in results)

    return json.dumps({'rows': results, 'total': round(total_amount, 2), 'n': len(results)})
